interface Transport { deliver(): void; }
class Truck implements Transport {
  deliver() { console.log("Deliver by truck"); }
}
class Ship implements Transport {
  deliver() { console.log("Deliver by ship"); }
}

function createTransport(type: string): Transport {
  return type === "truck" ? new Truck() : new Ship();
}

interface Notifier {
  send(message: string): Promise<void>;
}

function createNotifier(channel: "email" | "sms" | "push"): Notifier {
  switch (channel) {
    case "email":
      return new EmailNotifier();
    case "sms":
      return new SmsNotifier();
    case "push":
      return new PushNotifier();
  }
}

// Caller does not know or care which class it got
const notifier = createNotifier(config.channel);
await notifier.send("Welcome");

function makeUser(overrides: Partial<User> = {}): User {
  return {
    id: "00000000-0000-0000-0000-000000000000",
    name: "Test User",
    email: "test@example.com",
    role: "member",
    ...overrides,
  };
}

const admin = makeUser({ role: "admin" });
